use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let matrix = input.as_array().unwrap();
    let rows = matrix.len();
    let cols = matrix[0].as_array().unwrap().len();
    let mut result = vec![vec![0; cols]; rows];

    for i in 0..rows {
        for j in 0..cols {
            result[j][rows - 1 - i] = matrix[i][j].as_i64().unwrap();
        }
    }

    Value::Array(result)
}
